require dirname(__DIR__).'/includes/bootstrap.php';require APP_ROOT.'/services/catalog.php';$me=require_permission('QUAN_LY_KHO');
handle_form(function()use($me){$vin=post('vin');$cfg=post('cau_hinh');must(($vin==='')!==($cfg===''),'Chọn một VIN hoặc một cấu hình.');if($vin){$x=db_one('SELECT * FROM xe WHERE so_khung_vin=?',[$vin]);must($x&&scope_showroom($me,$x['ma_showroom']),'Xe ngoài phạm vi.',403);}else must($me['quyen']==='ADMIN'&&db_one('SELECT 1 FROM cau_hinh_xe WHERE ma_cau_hinh=?',[$cfg]),'Cấu hình không hợp lệ.');$f=upload_file($_FILES['file']??[],false,false,true);$type=$f['mime']==='video/mp4'?'VIDEO':(post('loai')==='ANH_360'?'ANH_360':'ANH');transaction(function()use($f,$cfg,$vin,$type){execute('INSERT INTO tep_xe(ma_cau_hinh,so_khung_vin,loai,duong_dan,thu_tu) VALUES (?,?,?,?,?)',[$cfg?:null,$vin?:null,$type,$f['path'],max(0,(int)post('thu_tu'))]);if($vin&&$type==='ANH')execute('UPDATE xe SET hinh_anh=? WHERE so_khung_vin=?',[$f['path'],$vin]);audit('TAI_ANH','tep_xe',(string)insert_id(),null,['path'=>$f['path']]);});},'admin/upload_anh.php');
page_start('Thư viện xe','JPEG, PNG, WebP tối đa 5 MB; MP4 tối đa 30 MB.');echo '<div class="panel">';token_form();field('vin','VIN (để trống nếu dùng ảnh cấu hình)');select_field('cau_hinh','Cấu hình',choices('SELECT * FROM cau_hinh_xe','ma_cau_hinh','ten_cau_hinh'));select_field('loai','Loại ảnh',['ANH'=>'Ảnh thường','ANH_360'=>'Bộ ảnh 360'],'ANH');field('thu_tu','Thứ tự trong bộ ảnh',0,'number');field('file','Chọn tệp','','file','required accept="image/jpeg,image/png,image/webp,video/mp4"');echo '<button>Tải lên</button></form></div>';page_end();
